<template>
  <div class="inventory-management">
    <!-- 页面标题与操作按钮 -->
    <div class="header">
      <h2>库存管理</h2>
      <el-button type="primary" @click="handleAdd">+ 新增商品</el-button>
    </div>

    <!-- 搜索与筛选区域 -->
    <el-card class="filter-card" shadow="never">
      <el-form :inline="true" :model="searchForm" size="small">
        <el-form-item label="商品名称">
          <el-input v-model="searchForm.productName" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="SKU">
          <el-input v-model="searchForm.sku" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="仓库">
          <el-input v-model="searchForm.warehouse" placeholder="请输入" clearable />
        </el-form-item>
        <el-form-item label="库存预警">
          <el-select v-model="warningFilter" placeholder="全部" clearable style="width: 120px">
            <el-option label="低于阈值" value="below" />
            <el-option label="正常" value="normal" />
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="handleSearch">查询</el-button>
          <el-button @click="resetSearch">重置</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 库存列表表格 -->
    <el-card class="table-card" shadow="never">
      <el-table :data="paginatedData" border stripe style="width: 100%">
        <el-table-column prop="productName" label="商品名称" min-width="150" />
        <el-table-column prop="sku" label="SKU" width="120" />
        <el-table-column prop="quantity" label="库存数量" width="100" />
        <el-table-column prop="warehouse" label="仓库位置" min-width="120" />
        <el-table-column prop="threshold" label="预警阈值" width="100" />
        <el-table-column label="库存状态" width="100">
          <template v-slot:default="scope">
            <el-tag :type="scope.row.quantity <= scope.row.threshold ? 'danger' : 'success'" size="small">
              {{ scope.row.quantity <= scope.row.threshold ? '低于阈值' : '正常' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="200" fixed="right">
          <template v-slot:default="scope">
            <el-button type="text" size="small" @click="handleEdit(scope.row)">编辑</el-button>
            <el-button type="text" size="small" @click="handleView(scope.row)">详情</el-button>
            <el-button type="text" size="small" style="color: #f56c6c" @click="handleDelete(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页组件 -->
      <el-pagination
        class="pagination"
        @current-change="handlePageChange"
        @size-change="handleSizeChange"
        :current-page="currentPage"
        :page-sizes="[10, 20, 50, 100]"
        :page-size="pageSize"
        layout="total, sizes, prev, pager, next, jumper"
        :total="filteredData.length"
      />
    </el-card>

    <!-- 新增/编辑库存对话框 -->
    <el-dialog
      :title="dialogType === 'add' ? '新增商品' : '编辑商品'"
      v-model:visible="dialogVisible"
      width="500px"
      @close="resetForm"
    >
      <el-form ref="inventoryForm" :model="currentItem" :rules="formRules" label-width="100px">
        <el-form-item label="商品名称" prop="productName">
          <el-input v-model="currentItem.productName" placeholder="请输入商品名称" />
        </el-form-item>
        <el-form-item label="SKU" prop="sku">
          <el-input v-model="currentItem.sku" placeholder="请输入SKU" />
        </el-form-item>
        <el-form-item label="库存数量" prop="quantity">
          <el-input-number v-model="currentItem.quantity" :min="0" style="width: 100%" />
        </el-form-item>
        <el-form-item label="仓库位置" prop="warehouse">
          <el-input v-model="currentItem.warehouse" placeholder="请输入仓库位置" />
        </el-form-item>
        <el-form-item label="预警阈值" prop="threshold">
          <el-input-number v-model="currentItem.threshold" :min="0" style="width: 100%" />
        </el-form-item>
      </el-form>
      <template v-slot:footer>
        <span class="dialog-footer">
          <el-button @click="dialogVisible = false">取 消</el-button>
          <el-button type="primary" @click="saveItem">确 定</el-button>
        </span>
      </template>
    </el-dialog>

    <!-- 查看详情对话框 -->
    <el-dialog title="商品详情" v-model:visible="detailVisible" width="500px">
      <el-descriptions :column="1" border>
        <el-descriptions-item label="商品名称">{{ viewItem.productName }}</el-descriptions-item>
        <el-descriptions-item label="SKU">{{ viewItem.sku }}</el-descriptions-item>
        <el-descriptions-item label="库存数量">{{ viewItem.quantity }}</el-descriptions-item>
        <el-descriptions-item label="仓库位置">{{ viewItem.warehouse }}</el-descriptions-item>
        <el-descriptions-item label="预警阈值">{{ viewItem.threshold }}</el-descriptions-item>
        <el-descriptions-item label="库存状态">
          <el-tag :type="viewItem.quantity <= viewItem.threshold ? 'danger' : 'success'">
            {{ viewItem.quantity <= viewItem.threshold ? '低于阈值' : '正常' }}
          </el-tag>
        </el-descriptions-item>
      </el-descriptions>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'InventoryManagement',
  data() {
    return {
      // 模拟库存数据
      allItems: [
        {
          id: 1,
          productName: '笔记本电脑',
          sku: 'SKU-001',
          quantity: 15,
          warehouse: 'A区-01货架',
          threshold: 10
        },
        {
          id: 2,
          productName: '无线鼠标',
          sku: 'SKU-002',
          quantity: 8,
          warehouse: 'B区-03货架',
          threshold: 10
        },
        {
          id: 3,
          productName: '机械键盘',
          sku: 'SKU-003',
          quantity: 5,
          warehouse: 'A区-02货架',
          threshold: 5
        }
      ],
      searchForm: {
        productName: '',
        sku: '',
        warehouse: ''
      },
      warningFilter: '', // '' 全部, 'below' 低于阈值, 'normal' 正常
      currentPage: 1,
      pageSize: 10,
      dialogVisible: false,
      dialogType: 'add',
      currentItem: this.getEmptyItem(),
      detailVisible: false,
      viewItem: {},
      formRules: {
        productName: [{ required: true, message: '请输入商品名称', trigger: 'blur' }],
        sku: [{ required: true, message: '请输入SKU', trigger: 'blur' }],
        quantity: [{ required: true, message: '请输入库存数量', trigger: 'blur' }],
        warehouse: [{ required: true, message: '请输入仓库位置', trigger: 'blur' }],
        threshold: [{ required: true, message: '请输入预警阈值', trigger: 'blur' }]
      }
    }
  },
  computed: {
    filteredData() {
      return this.allItems.filter(item => {
        const matchName = !this.searchForm.productName || item.productName.includes(this.searchForm.productName)
        const matchSku = !this.searchForm.sku || item.sku.includes(this.searchForm.sku)
        const matchWarehouse = !this.searchForm.warehouse || item.warehouse.includes(this.searchForm.warehouse)
        let matchWarning = true
        if (this.warningFilter === 'below') {
          matchWarning = item.quantity <= item.threshold
        } else if (this.warningFilter === 'normal') {
          matchWarning = item.quantity > item.threshold
        }
        return matchName && matchSku && matchWarehouse && matchWarning
      })
    },
    paginatedData() {
      const start = (this.currentPage - 1) * this.pageSize
      const end = start + this.pageSize
      return this.filteredData.slice(start, end)
    }
  },
  methods: {
    getEmptyItem() {
      return {
        id: null,
        productName: '',
        sku: '',
        quantity: 0,
        warehouse: '',
        threshold: 0
      }
    },
    handleSearch() {
      this.currentPage = 1
    },
    resetSearch() {
      this.searchForm = { productName: '', sku: '', warehouse: '' }
      this.warningFilter = ''
      this.currentPage = 1
    },
    handleAdd() {
      this.dialogType = 'add'
      this.currentItem = this.getEmptyItem()
      this.dialogVisible = true
    },
    handleEdit(row) {
      this.dialogType = 'edit'
      this.currentItem = { ...row }
      this.dialogVisible = true
    },
    handleView(row) {
      this.viewItem = { ...row }
      this.detailVisible = true
    },
    handleDelete(row) {
      this.$confirm(`确认删除商品“${row.productName}”吗？`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        const index = this.allItems.findIndex(i => i.id === row.id)
        if (index !== -1) {
          this.allItems.splice(index, 1)
          if (this.paginatedData.length === 0 && this.currentPage > 1) {
            this.currentPage--
          }
        }
        this.$message.success('删除成功')
      }).catch(() => {})
    },
    saveItem() {
      this.$refs.inventoryForm.validate(valid => {
        if (valid) {
          if (this.dialogType === 'add') {
            const newId = Math.max(...this.allItems.map(i => i.id), 0) + 1
            const newItem = {
              ...this.currentItem,
              id: newId
            }
            this.allItems.push(newItem)
            this.$message.success('新增成功')
          } else {
            const index = this.allItems.findIndex(i => i.id === this.currentItem.id)
            if (index !== -1) {
              this.allItems[index] = { ...this.currentItem }
            }
            this.$message.success('编辑成功')
          }
          this.dialogVisible = false
        }
      })
    },
    resetForm() {
      this.$refs.inventoryForm?.clearValidate()
      this.currentItem = this.getEmptyItem()
    },
    handlePageChange(page) {
      this.currentPage = page
    },
    handleSizeChange(size) {
      this.pageSize = size
      this.currentPage = 1
    }
  }
}
</script>

<style scoped>
.inventory-management {
  padding: 20px;
}
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}
.filter-card {
  margin-bottom: 20px;
}
.table-card {
  margin-bottom: 20px;
}
.pagination {
  margin-top: 20px;
  text-align: right;
}
</style>